BEGIN;
--
-- Create model CaliforniaDocketEntry
--
CREATE TABLE "search_californiadocketentry" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "date_created" timestamp with time zone NOT NULL, "date_modified" timestamp with time zone NOT NULL, "brief" boolean NOT NULL, "description" text NOT NULL, "notes" text NOT NULL, "date_filed" timestamp with time zone NULL, "submitted_by_name" text NOT NULL, "docket_id" integer NOT NULL, "submitted_by_id" integer NULL);
COMMENT ON COLUMN "search_californiadocketentry"."brief" IS 'Whether this entry appears in the "Briefs" table.';
COMMENT ON COLUMN "search_californiadocketentry"."description" IS 'The value in the description column on CA''s site.';
COMMENT ON COLUMN "search_californiadocketentry"."notes" IS 'The value in the notes column on CA''s site.';
COMMENT ON COLUMN "search_californiadocketentry"."date_filed" IS 'Date filed column from briefs table (when available).';
COMMENT ON COLUMN "search_californiadocketentry"."submitted_by_name" IS 'The name of the party that submitted this entry (when available).';
COMMENT ON COLUMN "search_californiadocketentry"."docket_id" IS 'The Docket this entry is associated with.';
COMMENT ON COLUMN "search_californiadocketentry"."submitted_by_id" IS 'FK to the case party that submitted this document may be null if the party cannot be found (when available).';
--
-- Create model CaliforniaDocument
--
CREATE TABLE "search_californiadocument" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "date_created" timestamp with time zone NOT NULL, "date_modified" timestamp with time zone NOT NULL, "sha1" varchar(40) NOT NULL, "page_count" integer NULL, "file_size" integer NULL, "filepath_local" varchar(1000) NOT NULL, "filepath_ia" varchar(1000) NOT NULL, "ia_upload_failure_count" smallint NULL, "thumbnail" varchar(100) NULL, "thumbnail_status" smallint NOT NULL, "plain_text" text NOT NULL, "ocr_status" smallint NULL, "url" varchar(250) NOT NULL, "processing_error" smallint NULL, "document_number" smallint NOT NULL, "description" text NOT NULL, "document_type" smallint NOT NULL, "document_type_raw" text NOT NULL, "file_name" varchar(255) NOT NULL, "docket_entry_id" integer NOT NULL);
COMMENT ON COLUMN "search_californiadocument"."processing_error" IS 'The processing error for the document, if any.';
COMMENT ON COLUMN "search_californiadocument"."document_number" IS 'Preserves ordering between scrape and DB';
COMMENT ON COLUMN "search_californiadocument"."description" IS 'A short description of the brief.';
COMMENT ON COLUMN "search_californiadocument"."document_type" IS 'Normalized document type (enum)';
COMMENT ON COLUMN "search_californiadocument"."document_type_raw" IS 'Raw document type text';
COMMENT ON COLUMN "search_californiadocument"."file_name" IS 'Name of the file provided by CA';
COMMENT ON COLUMN "search_californiadocument"."docket_entry_id" IS 'The Docket entry this document is associated with.';

--
-- Create index search_cali_filepat_bbb2e4_idx on field(s) filepath_local of model californiadocument
--
CREATE INDEX "search_cali_filepat_bbb2e4_idx" ON "search_californiadocument" ("filepath_local");
--
-- Create constraint unique_document_number_per_docket_entry on model californiadocument
--
ALTER TABLE "search_californiadocument" ADD CONSTRAINT "unique_document_number_per_docket_entry" UNIQUE ("docket_entry_id", "document_number");

ALTER TABLE "search_californiadocketentry" ADD CONSTRAINT "search_californiadoc_docket_id_756fc0c5_fk_search_do" FOREIGN KEY ("docket_id") REFERENCES "search_docket" ("id") DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "search_californiadocketentry" ADD CONSTRAINT "search_californiadoc_submitted_by_id_63625924_fk_people_db" FOREIGN KEY ("submitted_by_id") REFERENCES "people_db_party" ("id") DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX "search_californiadocketentry_date_created_3cff86a7" ON "search_californiadocketentry" ("date_created");
CREATE INDEX "search_californiadocketentry_date_modified_1c2b146c" ON "search_californiadocketentry" ("date_modified");
CREATE INDEX "search_californiadocketentry_docket_id_756fc0c5" ON "search_californiadocketentry" ("docket_id");
CREATE INDEX "search_californiadocketentry_submitted_by_id_63625924" ON "search_californiadocketentry" ("submitted_by_id");
ALTER TABLE "search_californiadocument" ADD CONSTRAINT "search_californiadoc_docket_entry_id_00f0b407_fk_search_ca" FOREIGN KEY ("docket_entry_id") REFERENCES "search_californiadocketentry" ("id") DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX "search_californiadocument_date_created_a398d6e1" ON "search_californiadocument" ("date_created");
CREATE INDEX "search_californiadocument_date_modified_c9432415" ON "search_californiadocument" ("date_modified");
CREATE INDEX "search_californiadocument_docket_entry_id_00f0b407" ON "search_californiadocument" ("docket_entry_id");
COMMIT;
